procedure:public.create_organization(tex.definition:
CREATE OR REPLACE FUNCTION public.create_organization(p_name text, p_base_currency character DEFAULT 'EGP'::bpchar, p_country_code character DEFAULT 'EG'::bpchar, p_timezone text DEFAULT 'Africa/Cairo'::text, p_legal_name text DEFAULT NULL::text, p_fiscal_year_start_month smallint DEFAULT 1)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_org_id uuid;
  v_slug   text;
  v_base   text;
  v_suffix int := 0;
  v_user   uuid := auth.uid();
begin
  if v_user is null then
    raise exception 'TENANT_ACCESS_DENIED: authentication required'
      using errcode = '42501';
  end if;

  if p_name is null or char_length(trim(p_name)) = 0 then
    raise exception 'INVALID_INPUT: organization name is required'
      using errcode = '22023';
  end if;

  if not exists (select 1 from public.currencies c
                 where c.code = p_base_currency and c.is_active) then
    raise exception 'INVALID_CURRENCY: % is not a supported currency', p_base_currency
      using errcode = '22023';
  end if;

  -- Slug must satisfy organizations_slug_format: 3+ chars, alphanumeric edges.
  v_base := app.slugify(p_name);
  if char_length(v_base) < 3 then
    v_base := v_base || '-org';
  end if;
  v_base := left(v_base, 58);
  v_slug := v_base;

  while exists (select 1 from public.organizations o where o.slug = v_slug) loop
    v_suffix := v_suffix + 1;
    v_slug := v_base || '-' || v_suffix::text;
  end loop;

  insert into public.organizations (
    name, slug, legal_name, country_code, timezone, base_currency,
    fiscal_year_start_month, created_by
  )
  values (
    trim(p_name), v_slug, p_legal_name, upper(p_country_code), p_timezone,
    p_base_currency, p_fiscal_year_start_month, v_user
  )
  returning id into v_org_id;

  insert into public.organization_settings (organization_id, default_transaction_currency)
  values (v_org_id, p_base_currency);

  -- The creator is the owner. This is the only place a membership is created
  -- without an invitation.
  insert into public.organization_members (organization_id, user_id, role, status)
  values (v_org_id, v_user, 'owner', 'active');

  perform app.seed_chart_of_accounts(v_org_id);
  perform app.seed_categories(v_org_id);

  update public.profiles p
  set default_organization_id = v_org_id
  where p.id = v_user and p.default_organization_id is null;

  perform app.write_audit(
    v_org_id, 'organization.created', 'organization', v_org_id,
    null, jsonb_build_object('name', trim(p_name), 'base_currency', p_base_currency)
  );

  return v_org_id;
end;
$function$

procedure:public.dashboard_summary(uuid,.source_code:
declare
  v_as_of        date := coalesce(p_as_of_date, app.org_today(p_organization_id));
  v_month_start  date := date_trunc('month', v_as_of)::date;
  v_prev_start   date := (date_trunc('month', v_as_of) - interval '1 month')::date;
  v_prev_end     date := (date_trunc('month', v_as_of) - interval '1 day')::date;
  v_assets       bigint;
  v_liabilities  bigint;
  v_cash         bigint;
  v_receivable   bigint;
  v_payable      bigint;
  v_revenue      bigint;
  v_expenses     bigint;
  v_prev_revenue bigint;
  v_prev_expenses bigint;
begin
  perform app.require_capability(p_organization_id, 'reports.read');

  with balances as (
    select
      a.type, a.subtype, a.is_liquid,
      case when a.normal_balance = 'debit'
           then coalesce(sum(e.base_amount_minor) filter (where e.side = 'debit'), 0)
              - coalesce(sum(e.base_amount_minor) filter (where e.side = 'credit'), 0)
           else coalesce(sum(e.base_amount_minor) filter (where e.side = 'credit'), 0)
              - coalesce(sum(e.base_amount_minor) filter (where e.side = 'debit'), 0)
      end as amount
    from public.accounts a
    left join public.transaction_entries e
      on e.account_id = a.id
     and e.posted_at is not null
     and e.entry_date <= v_as_of
    where a.organization_id = p_organization_id
    group by a.id, a.type, a.subtype, a.is_liquid
  )
  select
    coalesce(sum(amount) filter (where type = 'asset'), 0),
    coalesce(sum(amount) filter (where type = 'liability'), 0),
    coalesce(sum(amount) filter (where is_liquid), 0),
    coalesce(sum(amount) filter (where subtype = 'accounts_receivable'), 0),
    coalesce(sum(amount) filter (where subtype = 'accounts_payable'), 0)
  into v_assets, v_liabilities, v_cash, v_receivable, v_payable
  from balances;

  select
    coalesce(sum(case when a.type = 'revenue'
                      then case when e.side = 'credit' then e.base_amount_minor
                                else -e.base_amount_minor end end), 0),
    coalesce(sum(case when a.type = 'expense'
                      then case when e.side = 'debit' then e.base_amount_minor
                                else -e.base_amount_minor end end), 0)
  into v_revenue, v_expenses
  from public.transaction_entries e
  join public.accounts a on a.id = e.account_id
  where e.organization_id = p_organization_id
    and e.posted_at is not null
    and e.entry_date between v_month_start and v_as_of;

  select
    coalesce(sum(case when a.type = 'revenue'
                      then case when e.side = 'credit' then e.base_amount_minor
                                else -e.base_amount_minor end end), 0),
    coalesce(sum(case when a.type = 'expense'
                      then case when e.side = 'debit' then e.base_amount_minor
                                else -e.base_amount_minor end end), 0)
  into v_prev_revenue, v_prev_expenses
  from public.transaction_entries e
  join public.accounts a on a.id = e.account_id
  where e.organization_id = p_organization_id
    and e.posted_at is not null
    and e.entry_date between v_prev_start and v_prev_end;

  return jsonb_build_object(
    'as_of',                v_as_of,
    'base_currency',        app.org_base_currency(p_organization_id),
    'total_assets_minor',   v_assets,
    'total_liabilities_minor', v_liabilities,
    'net_worth_minor',      v_assets - v_liabilities,
    'cash_and_bank_minor',  v_cash,
    'accounts_receivable_minor', v_receivable,
    'accounts_payable_minor',    v_payable,
    'revenue_this_month_minor',  v_revenue,
    'expenses_this_month_minor', v_expenses,
    'net_profit_this_month_minor', v_revenue - v_expenses,
    'revenue_previous_month_minor',  v_prev_revenue,
    'expenses_previous_month_minor', v_prev_expenses,
    'net_profit_previous_month_minor', v_prev_revenue - v_prev_expenses
  );
end;

procedure:public.get_limit(uuid,text).source_code:
select case
  when not app.is_org_member(p_organization_id) then 0::bigint
  else (
